component.script:
"""Redis Cache -- read and write keys in the organization's in-cluster Redis.

One node runs one operation, chosen in the Inspector: GET, SET, DELETE, HGET,
HSET, HGETALL, EXISTS, KEYS or SCAN_VALUES. Key, field, value and pattern may
contain ${field} placeholders, filled from the incoming request_data (dotted
paths such as ${user.id} reach into nested objects).

A misconfigured node raises ValueError before Redis is touched, and a Redis
failure raises from the client. Neither is caught: a write that did not happen
must fail the run, never be reported as done.
"""

import json
import re

import perceivo

_OPERATIONS = ("GET", "SET", "DELETE", "HGET", "HSET", "HGETALL", "EXISTS", "KEYS", "SCAN_VALUES")
_KEYED = ("GET", "SET", "DELETE", "HGET", "HSET", "HGETALL", "EXISTS")
_HASH_FIELD = ("HGET", "HSET")

# SCAN_VALUES reads at most this many keys, and at most this many items of
# each list, so a large keyspace cannot exhaust the run's memory.
_MAX_SCAN_KEYS = 200
_MAX_LIST_ITEMS = 100

_PLACEHOLDER = re.compile(r"\$\{([\w.]+)\}")


def _lookup(data, path: str):
    """Return (True, value) for a dotted path into data, or (False, None)."""
    value = data
    for part in path.split("."):
        if isinstance(value, dict) and part in value:
            value = value[part]
        elif isinstance(value, list) and part.isdigit() and int(part) < len(value):
            value = value[int(part)]
        else:
            return False, None
    return True, value


def _fill(label: str, template: str, data: dict) -> str:
    """Replace each ${path} in template with that value from data.

    Strings are inserted as they are; anything else (numbers, objects, lists)
    as JSON. A placeholder naming a field the data does not carry raises, so a
    missing input never turns into a write to the wrong key.
    """

    def _replace(match):
        found, value = _lookup(data, match.group(1))
        if not found:
            raise ValueError(
                f"{label} refers to ${{{match.group(1)}}}, but the incoming data has no such field."
            )
        return value if isinstance(value, str) else json.dumps(value)

    return _PLACEHOLDER.sub(_replace, template)


def _param(name: str, default: str = "") -> str:
    value = perceivo.params.get(name, default)
    return default if value is None else str(value)


def _ttl_seconds() -> int:
    """The TTL in whole seconds; 0 means the key never expires."""
    raw = perceivo.params.get("default_ttl_seconds", 0)
    try:
        ttl = int(raw or 0)
    except (TypeError, ValueError):
        raise ValueError(f"TTL is {raw!r}. Use a whole number of seconds, or 0 for no expiry.") from None
    if ttl < 0:
        raise ValueError(f"TTL is {ttl}. Use a whole number of seconds, or 0 for no expiry.")
    return ttl


def _decode(value):
    """Turn bytes replies into text.

    The in-cluster client already decodes, but the SDK's local in-memory Redis
    answers in bytes, so this keeps both runtimes giving the same output.
    """
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    if isinstance(value, dict):
        return {_decode(k): _decode(v) for k, v in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_decode(item) for item in value]
    return value


async def _read_any(redis, key: str) -> dict:
    """Read one key for SCAN_VALUES, whatever its type.

    The platform's Redis client has no TYPE command, so each reader is tried in
    turn and Redis's WRONGTYPE reply means "not this type". Any other error is
    a real failure and is raised.
    """
    readers = (
        ("string", lambda: redis.get(key)),
        ("hash", lambda: redis.hgetall(key)),
        ("list", lambda: redis.lrange(key, 0, _MAX_LIST_ITEMS - 1)),
    )
    for kind, read in readers:
        try:
            value = _decode(await read())
        except Exception as exc:
            if "WRONGTYPE" in str(exc):
                continue
            raise
        if (kind == "string" and isinstance(value, str)) or (kind != "string" and value):
            return {"key": key, "type": kind, "value": value}
    return {"key": key, "type": "other", "value": None}


@perceivo.agent
async def redis_cache(input: perceivo.primitives.AgentInput) -> perceivo.primitives.AgentOutput:
    """Run one Redis operation and report its result as JSON.

    The result is both the JSON artifact and the response_data: always the
    operation and the full key it used, plus the operation's own field --
    value (GET, HGET, SET, HSET), fields (HGETALL), exists (EXISTS), deleted
    (DELETE), keys (KEYS, SCAN_VALUES) and entries (SCAN_VALUES).
    """
    data = input.request_data if isinstance(input.request_data, dict) else {}

    operation = _param("operation", "GET").strip().upper()
    if operation not in _OPERATIONS:
        raise ValueError(f"Operation is {operation!r}. Choose one of: {', '.join(_OPERATIONS)}.")

    prefix = _fill("Key Prefix", _param("key_prefix"), data).strip().rstrip(":")
    key = ""
    if operation in _KEYED:
        raw_key = _fill("Key", _param("key"), data).strip()
        if not raw_key:
            raise ValueError(f"Key is empty. {operation} needs the key to act on.")
        key = f"{prefix}:{raw_key}" if prefix else raw_key

    field = ""
    if operation in _HASH_FIELD:
        field = _fill("Hash Field", _param("field"), data).strip()
        if not field:
            raise ValueError(f"Hash Field is empty. {operation} needs the field within the hash.")

    value = _fill("Value", _param("value"), data) if operation in ("SET", "HSET") else ""
    ttl = _ttl_seconds() if operation in ("SET", "HSET") else 0

    pattern = ""
    if operation in ("KEYS", "SCAN_VALUES"):
        raw_pattern = _fill("Key Pattern", _param("pattern", "*"), data).strip() or "*"
        pattern = f"{prefix}:{raw_pattern}" if prefix else raw_pattern

    redis = await perceivo.cluster.redis.connect()
    perceivo.log.info(f"Redis Cache: {operation}", operation=operation, key=key or pattern)

    if operation == "GET":
        result = {"operation": operation, "key": key, "value": _decode(await redis.get(key))}
    elif operation == "SET":
        await redis.set(key, value, ttl_seconds=ttl or None)
        result = {"operation": operation, "key": key, "value": value}
    elif operation == "DELETE":
        result = {"operation": operation, "key": key, "deleted": bool(await redis.delete(key))}
    elif operation == "HGET":
        result = {"operation": operation, "key": key, "value": _decode(await redis.hget(key, field))}
    elif operation == "HSET":
        await redis.hset(key, field, value)
        if ttl:
            await redis.expire(key, ttl)
        result = {"operation": operation, "key": key, "value": value}
    elif operation == "HGETALL":
        result = {"operation": operation, "key": key, "fields": _decode(await redis.hgetall(key))}
    elif operation == "EXISTS":
        result = {"operation": operation, "key": key, "exists": bool(await redis.exists(key))}
    elif operation == "KEYS":
        result = {"operation": operation, "key": pattern, "keys": sorted(_decode(await redis.keys(pattern)))}
    else:
        matches = sorted(_decode(await redis.keys(pattern)))
        entries = [await _read_any(redis, k) for k in matches[:_MAX_SCAN_KEYS]]
        result = {"operation": operation, "key": pattern, "keys": matches, "entries": entries}

    return perceivo.primitives.AgentOutput(
        artifact=perceivo.primitives.Artifact(
            type=perceivo.primitives.ArtifactType.JSON, data=result, mime_type="application/json"
        ),
        response_data=result,
    )
